    표8_상담적용: [
        {"상황":"중년의 위기를 겪으며 인생을 돌아보는 분", "성경원리":"전도자도 모든 성취를 돌아보니 헛됨이었다. 이것은 절망이 아니라 방향 전환의 기회이다", "실제적용":"중년의 위기를 긍정적 전환점으로 활용하도록 돕고, 남은 인생의 방향을 하나님과 함께 재설정하도록 격려하라"},
        {"상황":"은퇴 후 자신의 커리어가 무의미했다고 느끼는 분", "성경원리":"해 아래에서의 수고는 그 자체로는 영원한 유익이 없으나, 하나님 안에서 행한 것은 결코 헛되지 않다(고전 15:58)", "실제적용":"과거의 수고 중 하나님의 은혜와 연결된 순간들을 함께 찾아보고, 남은 삶에서 영원한 유익을 위해 살도록 격려하라"},
        {"상황":"인생의 전환점에 서 있는 분", "성경원리":"돌이켜 봄이 전환의 시작이다. 세상적 방법이 실패했다면 하나님의 방법으로 전환할 때이다", "실제적용":"지금까지의 삶을 정직하게 평가하고, 하나님의 인도를 구하며 새로운 방향을 설정하도록 함께 기도하라"}
    ],
    표9_교차참조: [
        {"구절":"전 1:14", "연결점":"해 아래에서 행하는 모든 일을 보았노라 모두 다 헛되어 바람을 잡으려는 것이로다 - 동일한 결론", "구분":"구약"},
        {"구절":"전 2:17", "연결점":"해 아래에서 하는 일이 내게 괴로움이요 모두 다 헛되어 바람을 잡으려는 것임이로다", "구분":"구약"},
        {"구절":"시 127:1-2", "연결점":"여호와께서 집을 세우지 아니하시면 세우는 자의 수고가 헛되며", "구분":"구약"},
        {"구절":"전 12:13", "연결점":"하나님을 경외하고 그의 명령을 지킬지어다 이것이 사람의 본분이니라", "구분":"구약"},
        {"구절":"고전 15:58", "연결점":"주 안에서 여러분의 수고가 헛되지 않은 줄을 아나니", "구분":"신약"},
        {"구절":"벧전 1:18-19", "연결점":"조상이 물려준 헛된 행실에서 대속함을 받은 것은 그리스도의 보배로운 피로 된 것이니라", "구분":"신약"},
        {"구절":"빌 3:7-8", "연결점":"무엇이든지 내게 유익하던 것을 내가 그리스도를 위하여 다 해로 여김이라", "구분":"신약"},
        {"구절":"마 7:7", "연결점":"구하라 그러면 너희에게 주실 것이요 찾으라 그러면 찾아낼 것이요", "구분":"신약"}
    ]
